  ["NEWBIE_TOOLTIP_ABANDONQUEST"] = { "Abbandona la missione selezionata e la rimuove dal Registro missioni. Puoi sempre riaccettare una missione precedentemente abbandonata in un secondo momento. Abbandonare una missione non comporta nessuna penalità.", 0x09300fbc, "." },
  ["NEWBIE_TOOLTIP_ADDFRIEND"] = { "Aggiunge un personaggio all'elenco amici. Riceverai un messaggio quando un amico accede o si disconnette. Gli altri giocatori non possono sapere se sono o meno nel tuo elenco amici.", 0xa2ffd899, "." },
  ["NEWBIE_TOOLTIP_ADDMEMBER"] = { "Aggiunge un personaggio alla gilda.", 0x70d51515, "." },
  ["NEWBIE_TOOLTIP_BANDWIDTH"] = { "Mostra la larghezza di banda effettiva.", 0x60daa5c5, "." },
  ["NEWBIE_TOOLTIP_CHARACTER"] = { "Mostra informazioni sul tuo personaggio, tra cui l'equipaggiamento, le statistiche di combattimento e la reputazione.", 0x8875f6a2, "." },
  ["NEWBIE_TOOLTIP_CHATMENU"] = { "Comandi per comunicare con altri. Dal menu di chat puoi parlare con le persone che ti stanno vicino, inviare un messaggio privato, chiacchierare con i membri del tuo gruppo, salutare un amico o creare una macro.", 0xe2fbe5aa, "." },
  ["NEWBIE_TOOLTIP_DEMOTE"] = { "Degrada il personaggio selezionato.", 0x994aa01c, "." },
  ["NEWBIE_TOOLTIP_DISHONORABLE_KILLS"] = { "Ogni volta che partecipi nell'uccisione di un civile in PvP di livello così basso da non fornire esperienza (con il livello in grigio), ottieni un'uccisione disonorevole. Le uccisioni disonorevoli riducono leggermente il tuo grado e uccisioni disonorevoli multiple in un solo giorno hanno un effetto maggiore. Le uccisioni disonorevoli vengono applicate direttamente al tuo grado.", 0x1867ad87, "." },
  ["NEWBIE_TOOLTIP_DOWNLOAD_PERCENT"] = { "Indica la percentuale di gioco scaricata.", 0x2c0509f5, "." },
  ["NEWBIE_TOOLTIP_FRAMERATE"] = { "Indica quanto viene animato scorrevolmente il gioco. Un basso valore di framerate può essere incrementando modificando alcune opzioni video.", 0x89342243, "." },
  ["NEWBIE_TOOLTIP_FRIENDSTAB"] = { "Permette di gestire l'elenco dei giocatori con cui ti diverti a giocare. Riceverai una notifica quando un amico si connette o si disconnette.", 0x473fc50a, "." },
  ["NEWBIE_TOOLTIP_GROUPINVITE"] = { "Invita il personaggio selezionato a unirsi al tuo gruppo.", 0xa307ad7e, "." },
  ["NEWBIE_TOOLTIP_GUILDCONTROL"] = { "Permette di personalizzare i nomi di ogni grado di gilda e di stabilirne i privilegi.", 0x45f0a07d, "." },
  ["NEWBIE_TOOLTIP_GUILDREMOVE"] = { "Rimuove il personaggio selezionato dalla gilda.", 0xc1df4e02, "." },
  ["NEWBIE_TOOLTIP_GUILDTAB"] = { "Permette di visualizzare informazioni sulla gilda e sui personaggi che ne fanno parte. Se sei un ufficiale, da questa scheda puoi anche gestire la gilda.", 0x7cd32ab7, "." },
  ["NEWBIE_TOOLTIP_GUILD_INFORMATION"] = { "Clicca per visualizzare informazioni sulla tua gilda. Se sei un ufficiale o il capogilda, puoi aggiungere qui delle informazioni che potranno essere lette dai membri della tua gilda.", 0xb4c8599c, "." },
  ["NEWBIE_TOOLTIP_GUILD_MEMBER_OPTIONS"] = { "Clicca col pulsante destro su un membro di gilda per ulteriori opzioni.", 0xf16d24ea, "." },
  ["NEWBIE_TOOLTIP_HELP"] = { "Per risolvere il problema riscontrato, accedi all'aiuto di base online o contatta un Game Master (GM).", 0xf19e9aa5, "." },
  ["NEWBIE_TOOLTIP_HONORABLE_KILLS"] = { "Ogni volta che tu o un membro del tuo gruppo danneggia un giocatore in PvP che viene successivamente ucciso, guadagna un'uccisione onorevole. Ottieni un'uccisione onorevole solo se il livello del bersaglio è verde o superiore (esattamente come succede per l'esperienza con i mostri). Solo uccidendo i giocatori nemici puoi ottenere uccisioni onorevoli.", 0x7cac1334, "." },
  ["NEWBIE_TOOLTIP_HONOR_CONTRIBUTION_POINTS"] = { "L'onore viene guadagnato partecipando a delle uccisioni onorevoli in combattimenti PvP. La quantità di onore ottenuta è proporzionale al danno che tu (o il tuo gruppo) avete causato al personaggio ucciso. L'onore così ottenuto viene diviso tra tutti i membri del gruppo o dell'incursione. Inoltre otterrai meno onore se ucciderai lo stesso giocatore consecutivamente in un periodo di tempo troppo corto, fin quando l'uccisione stessa non fornirà più alcun onore.", 0x6995441d, "." },
  ["NEWBIE_TOOLTIP_IGNOREPLAYER"] = { "Aggiunge un personaggio all'elenco ignorati. Non riceverai più messaggi o altre comunicazioni testuali dai personaggi nell'elenco ignorati, ed essi non potranno comunicare con te in alcun modo.", 0x8e10dd0a, "." },
  ["NEWBIE_TOOLTIP_LATENCY"] = { "Indica il tempo necessario per comunicare con il server di gioco. Latenze molto alte (in rosso) possono indicare un problema con la tua connessione a Internet.", 0xa22e1634, "." },
  ["NEWBIE_TOOLTIP_LFGPARENT"] = { "Uno strumento per cercare un gruppo per completare una spedizione.", 0xd05fc90f, "." },
  ["NEWBIE_TOOLTIP_LOOKINGFORGUILDTAB"] = { "Ti permette di trovare una gilda.", 0x0d270ade, "." },
  ["NEWBIE_TOOLTIP_MAINMENU"] = { "Modifica le impostazioni, cambia l'assegnazione dei tasti o esci dal gioco.", 0x97dbb009, "." },
  ["NEWBIE_TOOLTIP_MEMORY"] = { "Indica la quantità di memoria utilizzata dagli add-on. Puoi accedere alla finestra di gestione degli add-on dalla schermata di selezione del personaggio.", 0x68f4dc90, "." },
  ["NEWBIE_TOOLTIP_PROMOTE"] = { "Promuove il personaggio selezionato.", 0x023b6914, "." },
  ["NEWBIE_TOOLTIP_PROTOCOLS"] = { "Questa è la versione del protocollo utilizzata dal gioco per connettersi al server. IPv6 è la tecnologia più recente attualmente disponibile, ma potrebbe causare problemi e non è ancora universalmente supportata.", 0xfbf6a5b5, "." },
  ["NEWBIE_TOOLTIP_QUESTLOG"] = { "L'elenco delle missioni attive attualmente a tua disposizione. Puoi avere al massimo 25 missioni attive contemporaneamente.", 0xbe69249f, "." },
  ["NEWBIE_TOOLTIP_RAF_SUMMON_LINKED"] = { "Clicca per evocare un membro del gruppo.", 0x28491d64, "." },
  ["NEWBIE_TOOLTIP_RAIDTAB"] = { "Permette di vedere o modificare il tuo gruppo di incursione. Le incursioni sono gruppi composti da più di cinque personaggi e vengono utilizzati per affrontare le sfide più difficili ai livelli più alti.", 0xc7b6216b, "." },
  ["NEWBIE_TOOLTIP_RANK"] = { "Il grado è il risultato ottenuto dal calcolo del sistema di gestione dell'onore. A seconda del rapporto tra il prestigio ottenuto nella settimana con il tuo grado attuale, questo può salire, scendere o restare invariato. I personaggi di livello superiore salgono più rapidamente di grado (e scendono più lentamente) rispetto a quelli di livello inferiore; inoltre, il grado aumenta più rapidamente se hai un grado inferiore rispetto a un grado superiore.", 0x320ae1d4, "." },
  ["NEWBIE_TOOLTIP_RANK_POSITION"] = { "La tua posizione nel grado. Questa barra indica quanto ti manca per ottenere il grado successivo o per scendere al grado precedente. La barra e l'onore vengono aggiornati solo una volta alla settimana.", 0x5fd6664e, "." },
  ["NEWBIE_TOOLTIP_REMOVEPLAYER"] = { "Rimuove il personaggio selezionato dall'elenco ignorati.", 0xe2849636, "." },
  ["NEWBIE_TOOLTIP_SENDMESSAGE"] = { "Invia un messaggio privato al personaggio selezionato.", 0x544c1d9c, "." },
  ["NEWBIE_TOOLTIP_SHAREQUEST"] = { "Permette di condividere una missione con tutti membri del tuo gruppo che ne soddisfano i requisiti. Alcune missioni, come quelle ottenute dagli oggetti, non possono essere condivise.", 0x7f3d927a, "." },
  ["NEWBIE_TOOLTIP_SOCIAL"] = { "Mostra informazioni su altri personaggi del gioco. Puoi utilizzare la finestra sociale per gestire l'elenco amici e l'elenco ignorati, e per vedere chi è attualmente online.", 0x6616cfbd, "." },
  ["NEWBIE_TOOLTIP_SPELLBOOK"] = { "Per accedere più facilmente a un incantesimo o a un'abilità, apri il grimorio e trascina col pulsante sinistro l'incantesimo o l'abilità in una barra delle azioni.", 0xab9bc796, "." },
  ["NEWBIE_TOOLTIP_TALENTS"] = { "Mostra i talenti disponibili per potenziare e specializzare il tuo personaggio.", 0x0ff69c8e, "." },
  ["NEWBIE_TOOLTIP_UNIT_FREE_FOR_ALL"] = { "In modalità Libero per Tutti, ogni membro del gruppo può depredare qualsiasi mostro che ha collaborato a uccidere. Il denaro viene automaticamente diviso tra tutti i membri.", 0xc16b9348, "." },
  ["NEWBIE_TOOLTIP_UNIT_GROUP_LOOT"] = { "In modalità Bottino di Gruppo, i membri depredano i mostri a turno come in modalità Rotazione Fissa, con l'eccezione che tutti i membri potranno tirare a sorte per gli oggetti sopra la soglia del bottino.", 0xb1401a54, "." },
  ["NEWBIE_TOOLTIP_UNIT_MASTER_LOOTER"] = { "In modalità Responsabile del Bottino, il capogruppo è l'unico autorizzato a depredare gli oggetti uguali o superiori alla soglia impostata. Gli oggetti sotto alla soglia e i soldi verranno distribuiti normalmente come in modalità Rotazione Fissa.", 0xb83526e3, "." },
  ["NEWBIE_TOOLTIP_UNIT_NEED_BEFORE_GREED"] = { "In modalità Necessità prima di Bramosia, il bottino viene distribuito come in modalità Rotazione Fissa. Qualsiasi oggetto sopra la soglia impostata verrà tirato a sorte dai membri del gruppo che ne possono fare uso.", 0xd60d2ead, "." },
  ["NEWBIE_TOOLTIP_UNIT_OPT_OUT_LOOT"] = { "Se attivato, potrai depredare solo oggetti di missione, oggetti che tutti quanti hanno passato od oggetti ricevuti direttamente dal responsabile del bottino.", 0xa2894352, "." },
  ["NEWBIE_TOOLTIP_UNIT_ROUND_ROBIN"] = { "In modalità Rotazione Fissa, ogni membro del gruppo depreda a turno i mostri che collabora a uccidere. Il denaro viene automaticamente diviso tra tutti i membri.", 0xe487fce6, "." },
  ["NEWBIE_TOOLTIP_WHOTAB"] = { "Permette di trovare la posizione di altri giocatori nel mondo.", 0xdc8a982c, "." },
  ["NEWBIE_TOOLTIP_WORLDMAP"] = { "Mentre esplori una zona, nuove aree di interesse diventeranno visibili sulla mappa. Clicca col pulsante sinistro per ingrandire e col pulsante destro per ridurre l'ingrandimento.", 0x68dfc622, "." },
  ["NEWBIE_TOOLTIP_XPBAR"] = { "Questa è la quantità di esperienza (PE) che hai guadagnato finora. Il colore della barra dell'esperienza indica il tuo stato di riposo: azzurro significa che sei riposato, mentre viola è lo stato normale. I personaggi riposati guadagnano il doppio dell'esperienza dall'uccisione dei mostri, ma così facendo si stancano. Puoi aumentare il tuo stato di riposo passando del tempo in una capitale o in una locanda o disconnettendoti mentre sei al loro interno.", 0x69eb0791, "." },
